  projectId: r3.project_id,
  protocolId: r3.protocol_id,
  protocolVersion: r3.protocol_version,
  engineVersion: r3.engine_version,
  state: r3.state,
  intent: r3.intent,
  risk: r3.risk,
  sourceIssueId: r3.source_issue_id ?? null,
  sourceIssueNumber: r3.source_issue_number ?? null,
