  approvedPlanHash: r3.approved_plan_hash ?? null,
  baseCommit: r3.base_commit ?? null,
  headSha: r3.head_sha ?? null,
  activeBranch: r3.active_branch ?? null,
  worktreePath: r3.worktree_path ?? null,
