  const root = await makeFixtureRepo(files2);
  const seq = [];
  const com = [];
  for (let i = 0; i < repetitions; i++) {
    seq.push(await sequential(root));
    const c = sandboxSupport().ok ? await composed(root) : null;
    if (c) com.push(c);
  }
